lessons.challengeSolution:
setcpm(80/4)
const key = "C:minor"
const pad = n("[0,2,4,6]").scale(key).s("supersaw").gain(.4).attack(1).release(2).lpf(perlin.range(300, 1500).slow(8))
  .room(.9).delay(.6).delaysync(3/8).delayfeedback(.8).orbit(2)
const pulse = n("0*4").scale(key).s("sine").decay(.3).sustain(0).gain(.5)
const intro = stack(pad)
const body = stack(pad, pulse)
arrange([8, intro], [16, body], [8, intro])
